-- V-Learn: course progress (per user) + a SHARED lesson-content cache so each
-- lesson is generated by the LLM only once ever. Run after 0003.

-- Per-user lesson completion (drives linear unlock + dashboard).
create table if not exists public.lesson_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  lesson_id text not null,
  completed_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);

alter table public.lesson_progress enable row level security;
create policy "lesson_progress_all_own" on public.lesson_progress
  for all using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- Shared, content-addressed cache (same for everyone → generate once).
create table if not exists public.lesson_content (
  lesson_id text primary key,
  content jsonb not null,
  created_at timestamptz not null default now()
);

alter table public.lesson_content enable row level security;
-- Any authenticated user can read the cache and populate a missing entry.
create policy "lesson_content_read" on public.lesson_content
  for select to authenticated using (true);
create policy "lesson_content_insert" on public.lesson_content
  for insert to authenticated with check (true);
